<template>
  <VueScroll :ops="mergedOps">
    <slot />
  </VueScroll>
</template>

<script>
import { Component, Prop, Vue } from "vue-property-decorator";
import "vue-virtual-scroller/dist/vue-virtual-scroller.css";
import VueScroll from "vuescroll/dist/vuescroll-native";

@Component({
  components: {
    VueScroll,
  },
})
export default class ScrollContainer extends Vue {
  /**
   * @see options https://vuescrolljs.yvescoding.org/guide/configuration.html#vuescroll
   */
  @Prop({
    type: Object,
    default: () => {},
  })
  options;

  get mergedOps() {
    const mergedOps = {
      // default settings
      locking: true,
      bar: {
        background: "rgba(0, 0, 0, 0.5)",
        size: "4px",
      },

      // merges any of the overrides that are provided via the `options` prop
      ...(this.options || {}),
    };

    return mergedOps;
  }
}
</script>
